#!/usr/bin/env node
// Builds the verb pages' data from the course files: every verb in a course's
// vocabulary, with its full conjugation generated by RosaeNLG's verb libraries
// (french-verbs + Lefff data, english-verbs-helper). Dev dependencies only: the
// app ships the generated JSON, not the libraries.
//
// Output, per course language:
//   src/data/verbs/<lang>-index.json  — verb list (small, loaded with the page)
//   src/data/verbs/<lang>-forms.json  — conjugations (loaded when a verb is opened)
//   src/data/verbs/<lang>-examples.json — an example sentence per tense, with translations
//                                         (loaded with the forms). Simple tenses use a real
//                                         sentence from the course when there is one; the rest
//                                         are built by scripts/verb-examples.mjs.
//
// Usage: node scripts/generate-verbs.mjs   (re-run after adding or editing lessons)

import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { createRequire } from 'node:module'
import { englishTenseExample, frenchTenseExample } from './verb-examples.mjs'

const require = createRequire(import.meta.url)
const OUT = 'src/data/verbs'
mkdirSync(OUT, { recursive: true })

// A vocabulary item is a verb when its Spanish translation is an infinitive.
// Spanish nouns that look like infinitives:
const NOT_INFINITIVES = new Set([
  'ayer', 'dólar', 'hogar', 'azúcar', 'suéter', 'bar', 'lugar', 'mar', 'collar', 'mujer', 'taller',
  'placer', 'alquiler', 'altar', 'militar', 'familiar', 'popular', 'regular', 'particular', 'similar',
  'celular', 'par', 'menor', 'mayor', 'cráter', 'carácter', 'póster', 'láser', 'líder',
  'chófer', 'máster', 'tráiler', 'cóctel', 'ámbar', 'nácar', 'néctar', 'pilar', 'hangar', 'bienestar',
  'amanecer', 'atardecer', 'anochecer', 'deber', 'poder', 'saber', 'parecer', 'ser', 'haber',
])
// …except the ones that are verbs too (kept when the course word is a verb)
const VERB_ANYWAY = new Set(['deber', 'poder', 'saber', 'parecer', 'ser', 'haber', 'amanecer', 'atardecer', 'anochecer'])

function looksLikeInfinitive(es) {
  const first = (es ?? '').trim().split(/[\s/,(]/)[0].toLowerCase()
  if (!/(ar|er|ir|ír)(se)?$/.test(first)) return false
  return !NOT_INFINITIVES.has(first) || VERB_ANYWAY.has(first)
}

// Core verbs every learner needs; courses teach them through grammar, so they're
// often missing from vocabulary lists. Added first, tagged as essential (lesson 0).
const ESSENTIAL = {
  fr: [
    ['être', 'to be', 'ser / estar'], ['avoir', 'to have', 'tener / haber'], ['aller', 'to go', 'ir'],
    ['faire', 'to do / to make', 'hacer'], ['pouvoir', 'can / to be able to', 'poder'], ['vouloir', 'to want', 'querer'],
    ['devoir', 'must / to have to', 'deber'], ['dire', 'to say', 'decir'], ['voir', 'to see', 'ver'],
    ['prendre', 'to take', 'tomar'], ['venir', 'to come', 'venir'], ['savoir', 'to know (a fact)', 'saber'],
    ['parler', 'to speak', 'hablar'], ["s'appeler", 'to be called', 'llamarse'], ['habiter', 'to live', 'vivir'],
    ['manger', 'to eat', 'comer'], ['boire', 'to drink', 'beber'], ['aimer', 'to like / to love', 'gustar / amar'],
    ['mettre', 'to put', 'poner'], ['donner', 'to give', 'dar'], ['partir', 'to leave', 'irse / salir'],
    ['travailler', 'to work', 'trabajar'], ['comprendre', 'to understand', 'entender'], ['connaître', 'to know (someone)', 'conocer'],
  ],
  en: [
    ['be', 'ser / estar'], ['have', 'tener / haber'], ['do', 'hacer'], ['go', 'ir'], ['get', 'conseguir / obtener'],
    ['make', 'hacer / fabricar'], ['say', 'decir'], ['see', 'ver'], ['come', 'venir'], ['take', 'tomar / llevar'],
    ['know', 'saber / conocer'], ['think', 'pensar'], ['give', 'dar'], ['tell', 'contar / decir'], ['speak', 'hablar'],
    ['understand', 'entender'], ['eat', 'comer'], ['drink', 'beber'], ['live', 'vivir'], ['work', 'trabajar'],
    ['like', 'gustar'], ['want', 'querer'], ['need', 'necesitar'], ['buy', 'comprar'],
  ],
}

function translationsOf(item) {
  const t = {}
  for (const [k, v] of Object.entries(item)) if (k !== 'word' && typeof v === 'string' && /^[a-z]{2}$/.test(k)) t[k] = v
  return t
}

function* vocabulary(lang) {
  for (const [word, ...t] of ESSENTIAL[lang]) {
    const item = lang === 'fr' ? { word, en: t[0], es: t[1] } : { word, es: t[0] }
    yield { item, lesson: 0, slug: null, essential: true }
  }
  for (const file of readdirSync(join('content', lang)).filter(f => /^(lecon|lesson)-\d+\.json$/.test(f)).sort()) {
    const d = JSON.parse(readFileSync(join('content', lang, file), 'utf8'))
    for (const item of d.vocabulary ?? []) yield { item, lesson: d.lesson, slug: d.slug }
  }
}

// ── French ────────────────────────────────────────────────────────────────────

function buildFrench() {
  const fv = require('french-verbs')
  const lefff = require('french-verbs-lefff/dist/conjugations.json')

  const PERSONS = ['je', 'tu', 'il/elle', 'nous', 'vous', 'ils/elles']
  const MOODS = [
    { name: 'Indicatif', tenses: [
      ['PRESENT', 'Présent'], ['PASSE_COMPOSE', 'Passé composé'], ['IMPARFAIT', 'Imparfait'],
      ['PLUS_QUE_PARFAIT', 'Plus-que-parfait'], ['PASSE_SIMPLE', 'Passé simple'],
      ['FUTUR', 'Futur simple'], ['FUTUR_ANTERIEUR', 'Futur antérieur'],
    ] },
    { name: 'Conditionnel', tenses: [['CONDITIONNEL_PRESENT', 'Présent'], ['CONDITIONNEL_PASSE_1', 'Passé']] },
    { name: 'Subjonctif', tenses: [
      ['SUBJONCTIF_PRESENT', 'Présent'], ['SUBJONCTIF_PASSE', 'Passé'],
      ['SUBJONCTIF_IMPARFAIT', 'Imparfait'], ['SUBJONCTIF_PLUS_QUE_PARFAIT', 'Plus-que-parfait'],
    ] },
    { name: 'Impératif', tenses: [['IMPERATIF_PRESENT', 'Présent']] },
  ]

  const elides = form => /^[aeiouyhâàäéèêëîïôöûùüœ]/i.test(form)
  function withSubject(person, form, subjunctive) {
    let subject = PERSONS[person]
    if (person === 0 && elides(form)) subject = "j'"
    const sep = subject.endsWith("'") ? '' : ' '
    let line = `${subject}${sep}${form}`
    if (subjunctive) line = (person === 2 || person === 5 ? "qu'" : 'que ') + line
    return line
  }

  const seen = new Map()
  for (const { item, lesson, slug, essential } of vocabulary('fr')) {
    const word = item.word.trim()
    const pronominal = /^(se |s')/.test(word)
    const infinitive = word.replace(/^(se |s')/, '')
    if (/\s/.test(infinitive) || !lefff[infinitive] || (!essential && !looksLikeInfinitive(item.es))) continue
    if (seen.has(word)) continue

    const aux = pronominal || fv.alwaysAuxEtre(infinitive) ? 'ETRE' : 'AVOIR'
    // Defective verbs (pleuvoir, pouvoir…) lack some forms: those are null
    const conj = (tense, person) => {
      try {
        return fv.getConjugation(
          lefff, infinitive, tense, person,
          { aux, agreeNumber: aux === 'ETRE' && person >= 3 ? 'P' : 'S' },
          pronominal, undefined, undefined, 'Act',
        )
      } catch {
        return null
      }
    }

    const forms = {}
    for (const mood of MOODS) {
      for (const [tense] of mood.tenses) {
        if (tense === 'IMPERATIF_PRESENT') {
          // Pronominal imperative: appelle-toi, appelons-nous, appelez-vous
          const reflexive = ['toi', 'nous', 'vous']
          forms[tense] = [1, 3, 4].map((p, i) => {
            if (!pronominal) return conj(tense, p)
            try {
              const base = fv.getConjugation(lefff, infinitive, tense, p, { aux: 'AVOIR' }, false, undefined, undefined, 'Act')
              return `${base}-${reflexive[i]}`
            } catch {
              return null
            }
          })
        } else {
          forms[tense] = [0, 1, 2, 3, 4, 5].map(p => {
            const form = conj(tense, p)
            return form && withSubject(p, form, tense.startsWith('SUBJONCTIF'))
          })
        }
      }
    }
    // Lefff lists the literary "je puis"; the everyday form is "je peux"
    if (infinitive === 'pouvoir' && forms.PRESENT) forms.PRESENT[0] = 'je peux'

    function participle(tense) {
      try { return fv.getConjugation(lefff, infinitive, tense, 0, { aux }, false, undefined, undefined, 'Act') } catch { return null }
    }
    // Drop tenses with no form at all (e.g. the imperative of pouvoir)
    for (const [k, v] of Object.entries(forms)) if (v.every(f => f == null)) delete forms[k]

    seen.set(word, {
      id: word,
      infinitive: word,
      translations: translationsOf(item),
      lesson, slug,
      essential: !!essential,
      pronominal,
      aux: aux === 'ETRE' ? 'être' : 'avoir',
      participles: { present: participle('PARTICIPE_PRESENT'), past: participle('PARTICIPE_PASSE') },
      forms,
    })
  }

  return {
    persons: PERSONS,
    imperativePersons: ['(tu)', '(nous)', '(vous)'],
    moods: MOODS.map(m => ({ name: m.name, tenses: m.tenses.map(([key, name]) => ({ key, name })) })),
    participleLabels: { present: 'Participe présent', past: 'Participe passé' },
    note: 'Avec « être », le participe passé s’accorde avec le sujet : elle est allée, elles sont allées.',
    verbs: [...seen.values()],
  }
}

// ── English ───────────────────────────────────────────────────────────────────

function buildEnglish() {
  const ev = require('english-verbs-helper')
  const info = ev.mergeVerbsData(
    require('english-verbs-irregular/dist/verbs.json'),
    require('english-verbs-gerunds/dist/gerunds.json'),
  )
  const PERSONS = ['I', 'you', 'he/she', 'we', 'you', 'they']
  const MOODS = [
    { name: 'Present', tenses: [
      ['SIMPLE_PRESENT', 'Simple present'], ['PROGRESSIVE_PRESENT', 'Present continuous'],
      ['PERFECT_PRESENT', 'Present perfect'], ['PERFECT_PROGRESSIVE_PRESENT', 'Present perfect continuous'],
    ] },
    { name: 'Past', tenses: [
      ['SIMPLE_PAST', 'Simple past'], ['PROGRESSIVE_PAST', 'Past continuous'],
      ['PERFECT_PAST', 'Past perfect'], ['PERFECT_PROGRESSIVE_PAST', 'Past perfect continuous'],
    ] },
    { name: 'Future', tenses: [
      ['SIMPLE_FUTURE', 'Simple future'], ['PROGRESSIVE_FUTURE', 'Future continuous'],
      ['PERFECT_FUTURE', 'Future perfect'], ['PERFECT_PROGRESSIVE_FUTURE', 'Future perfect continuous'],
    ] },
    { name: 'Conditional', tenses: [['CONDITIONAL_PRESENT', 'Present conditional'], ['CONDITIONAL_PERFECT', 'Perfect conditional']] },
    { name: 'Imperative', tenses: [['IMPERATIVE', 'Imperative']] },
  ]
  // Modal verbs have no full conjugation
  const MODALS = new Set(['can', 'could', 'should', 'must', 'may', 'might', 'will', 'would', 'shall', 'ought'])

  const seen = new Map()
  for (const { item, lesson, slug, essential } of vocabulary('en')) {
    const verb = item.word.trim().replace(/^to /, '')
    if (/\s/.test(verb) || MODALS.has(verb)) continue
    // -ing words in vocabulary lists are nouns or gerunds ("running"), not infinitives
    if (!essential && (!looksLikeInfinitive(item.es) || (/ing$/.test(verb) && verb.length > 5))) continue
    if (seen.has(verb)) continue

    const past = ev.getConjugation(info, verb, 'PARTICIPLE_PAST', 0, {})
    const forms = {}
    for (const mood of MOODS) {
      for (const [tense] of mood.tenses) {
        if (tense === 'IMPERATIVE') { forms[tense] = [verb, `let's ${verb}`, `don't ${verb}`]; continue }
        forms[tense] = [0, 1, 2, 3, 4, 5].map(p => {
          const form = tense === 'CONDITIONAL_PRESENT' ? `would ${verb}`
            : tense === 'CONDITIONAL_PERFECT' ? `would have ${past}`
            : ev.getConjugation(info, verb, tense, p, {})
          return `${PERSONS[p]} ${form}`
        })
      }
    }

    seen.set(verb, {
      id: verb,
      infinitive: `to ${verb}`,
      translations: translationsOf(item),
      lesson, slug,
      essential: !!essential,
      pronominal: false,
      aux: null,
      participles: { present: ev.getIngPart(info, verb), past },
      forms,
    })
  }

  return {
    persons: PERSONS,
    imperativePersons: ['(you)', '(let’s)', '(negative)'],
    moods: MOODS.map(m => ({ name: m.name, tenses: m.tenses.map(([key, name]) => ({ key, name })) })),
    participleLabels: { present: 'Present participle', past: 'Past participle' },
    note: null,
    verbs: [...seen.values()],
  }
}

// ── Examples ──────────────────────────────────────────────────────────────────
// Sentences from the course (phrases, arrange and translate exercises, which come
// with translations; story sentences as a fallback) that contain a form of the verb.

function courseSentences(lang) {
  const out = []
  for (const file of readdirSync(join('content', lang)).filter(f => /^(lecon|lesson)-\d+\.json$/.test(f)).sort()) {
    const d = JSON.parse(readFileSync(join('content', lang, file), 'utf8'))
    const add = (text, item, source) => {
      if (!text) return
      const translations = {}
      for (const k of ['en', 'es']) if (k !== lang && typeof item?.[k] === 'string') translations[k] = item[k]
      out.push({ text: text.trim(), translations, lesson: d.lesson, source })
    }
    for (const p of d.phrases ?? []) add(p.phrase, p, 'phrase')
    for (const a of d.arrange ?? []) add(a.sentence, a, 'arrange')
    for (const t of d.translate ?? []) add(t.answer, t, 'translate')
    for (const sentence of (d.story?.text ?? '').match(/[^.!?]+[.!?]+/g) ?? []) add(sentence, null, 'story')
  }
  return out
}

// Words of a sentence, lowercased, with French elisions split off (j'habite → habite)
function words(text) {
  return tokens(text).map(t => t.word)
}

// Tokens keep what the elision stripped (j', m', s'…) to tell who the subject is
function tokens(text) {
  return text.toLowerCase().replace(/[’]/g, "'").split(/[^\p{L}'-]+/u).filter(Boolean).map(raw => {
    const m = raw.match(/^([jmtslnd]|qu)'(.+)$/)
    return { word: (m ? m[2] : raw).replace(/'s$/, ''), elided: m ? m[1] : null }
  })
}

// Personal subject pronouns: a conjugated form right after one is unambiguous
const PRONOUNS = {
  fr: new Set(['je', 'tu', 'il', 'elle', 'on', 'nous', 'vous', 'ils', 'elles']),
  en: new Set(['i', 'you', 'he', 'she', 'it', 'we', 'they']),
}
const EN_AUX = new Set(['can', 'could', 'will', 'would', 'should', 'must', 'may', 'might', 'do', 'does', 'did', 'shall'])
// Simple tenses where a course sentence can be told apart by its verb form
const COURSE_TENSES = {
  fr: ['PRESENT', 'IMPARFAIT', 'FUTUR', 'CONDITIONNEL_PRESENT'],
  en: ['SIMPLE_PRESENT', 'SIMPLE_PAST'],
}
const NEEDED_TRANSLATIONS = { fr: ['en', 'es'], en: ['es'] }

/** Course sentences per simple tense: "<pronoun> <form>" with the form belonging to that tense only */
function courseExamplesByTense(lang, verb, sentences) {
  if (verb.pronominal) return {}
  const tenses = COURSE_TENSES[lang]
  const lastWords = Object.fromEntries(tenses.map(t => [t, new Set((verb.forms[t] ?? []).map(f => f && words(f).at(-1)).filter(Boolean))]))
  const tenseOf = word => {
    const owners = tenses.filter(t => lastWords[t].has(word))
    return owners.length === 1 ? owners[0] : null
  }
  const found = {}
  for (const sentence of sentences) {
    const n = sentence.toks.length
    if (n < 3 || n > 10) continue
    if (!NEEDED_TRANSLATIONS[lang].every(k => sentence.translations[k])) continue
    for (let i = 0; i < n; i++) {
      const { word, elided } = sentence.toks[i]
      const hasSubject = elided === 'j' || PRONOUNS[lang].has(sentence.toks[i - 1]?.word)
      // "Can you swim?": a modal before the subject means the verb is a bare infinitive
      if (lang === 'en' && EN_AUX.has(sentence.toks[i - 2]?.word)) break
      const tense = hasSubject && tenseOf(word)
      if (!tense) continue
      // Prefer the verb's own lesson, then the shortest sentence
      const score = (sentence.lesson === verb.lesson ? 0 : 100) + n
      if (!found[tense] || score < found[tense].score) {
        found[tense] = { score, example: { text: sentence.text, translations: sentence.translations, match: word } }
      }
      break
    }
  }
  return Object.fromEntries(Object.entries(found).map(([t, f]) => [t, f.example]))
}

function buildExamples(lang, verbs) {
  const sentences = courseSentences(lang).map(s => ({ ...s, toks: tokens(s.text) }))
  const examples = {}
  for (const verb of verbs) {
    const fromCourse = courseExamplesByTense(lang, verb, sentences)
    const perTense = {}
    for (const tense of Object.keys(verb.forms)) {
      const example = fromCourse[tense] ?? (lang === 'fr' ? frenchTenseExample(verb, tense, verb.forms) : englishTenseExample(verb, tense))
      if (example) perTense[tense] = example
    }
    examples[verb.id] = perTense
  }
  return examples
}

// ── Write ─────────────────────────────────────────────────────────────────────

for (const [lang, build] of [['fr', buildFrench], ['en', buildEnglish]]) {
  const data = build()
  data.verbs.sort((a, b) => a.lesson - b.lesson || a.infinitive.localeCompare(b.infinitive, lang))
  const index = {
    language: lang,
    moods: data.moods,
    persons: data.persons,
    imperativePersons: data.imperativePersons,
    participleLabels: data.participleLabels,
    note: data.note,
    verbs: data.verbs.map(v => Object.fromEntries(Object.entries(v).filter(([k]) => k !== 'forms'))),
  }
  const forms = Object.fromEntries(data.verbs.map(v => [v.id, v.forms]))
  writeFileSync(join(OUT, `${lang}-index.json`), JSON.stringify(index))
  writeFileSync(join(OUT, `${lang}-forms.json`), JSON.stringify(forms))
  const examples = buildExamples(lang, data.verbs)
  writeFileSync(join(OUT, `${lang}-examples.json`), JSON.stringify(examples))
  const tenses = Object.values(examples).reduce((n, e) => n + Object.keys(e).length, 0)
  const translated = Object.values(examples).reduce((n, e) => n + Object.values(e).filter(x => Object.keys(x.translations).length).length, 0)
  console.log(`${lang}: ${data.verbs.length} verbs, ${tenses} tense examples (${translated} translated)`)
}
